  <label class="f">${t('result')}<select data-r="${i}" data-k="result" ${ro?'disabled':''}>${['conforming','minor','major','ofi'].map(x=>`<option value="${x}" ${r.result===x?'selected':''}>${resLabel(x)}</option>`).join('')}</select></label>
